  {view==='summary'&&<section className="grid gap-4 lg:grid-cols-2"><div className="rounded-[2rem] border border-white/10 bg-white/[.035] p-5"><p className="text-xs font-black uppercase tracking-widest text-cyan-300">Objetivos de referencia</p><div className="mt-4 space-y-3">{goals.map(goal=><div key={goal.label} className="flex items-center justify-between rounded-2xl bg-black/20 p-4"><div><span className="text-xs text-slate-500">{goal.label}</span><b className="block text-lg">{goal.current??'—'}</b></div><div className="text-right"><span className={goal.ok?'text-xs font-black text-emerald-300':'text-xs font-black text-amber-300'}>{goal.ok?'EN OBJETIVO':'OBJETIVO'}</span><b className="block text-sm text-slate-300">{goal.target}</b></div></div>)}</div></div><div className="rounded-[2rem] border border-white/10 bg-white/[.035] p-5"><p className="text-xs font-black uppercase tracking-widest text-violet-300">Datos clave</p><MetricGrid items={[["Masa libre",show(latest.masaLibreGrasaKg," kg")],["VO₂ estimado",show(latest.vo2MaxEstimado)],["Plancha",show(latest.planchaSegundos," s")],["Salto horizontal",show(latest.saltoHorizontalCm," cm")],["Sit and reach",show(latest.sitAndReachCm," cm")],["Calidad",show(latest.calidadMedicion,"/100")]]}/>{latest.contextoMenstrual&&<p className="mt-4 rounded-xl bg-pink-500/10 p-3 text-xs text-pink-100">Contexto menstrual: {latest.faseMenstrual||'fase desconocida'}. Solo se usa para interpretar tendencias.</p>}</div></section>}
